import sqlite3
conn=sqlite3.connect('data/accounts.db')
try:
    rows=conn.execute('SELECT count(*) FROM legacy_accounts').fetchone()
    print('legacy_accounts', rows)
except Exception as e:
    print('legacy_accounts error', e)
try:
    rows=conn.execute('SELECT count(*) FROM accounts').fetchone()
    print('accounts', rows)
except Exception as e:
    print('accounts error', e)
try:
    rows=conn.execute('SELECT * FROM legacy_accounts LIMIT 3').fetchall()
    print(rows)
except Exception as e:
    print(e)
try:
    rows=conn.execute('SELECT * FROM accounts LIMIT 3').fetchall()
    print(rows)
except Exception as e:
    print(e)
